const cont = $('Contar Respostas Ativas').item.json;
const totalAtivas = Number(cont.total_ativas || 0);
const pontuando = Number(cont.pontuando || 0);
const s5 = totalAtivas > 0 ? Math.round((100 * pontuando / totalAtivas) * 100) / 100 : 0;

return [{ json: { s5_maturidade: s5, y: pontuando, total_perguntas_ativas: totalAtivas } }];

const analise = $('Buscar Última Análise Concluída').item.json;
const s5info = $('Montar S5').item.json;
const score = $('Executar Calcular Score').item.json;

const detalhesAnterior = analise.detalhes_calculo || {};
detalhesAnterior.d5 = { y: s5info.y, total: s5info.total_perguntas_ativas, s5: s5info.s5_maturidade };
detalhesAnterior.pesos_usados = score.pesos_usados;

const sobrescrita = analise.decisao_sobrescrita === true;

return [{ json: {
  analise_id: analise.analise_id,
  s5_maturidade: s5info.s5_maturidade,
  score_total: score.score_total,
  decisao: sobrescrita ? analise.decisao : score.decisao,
  status: sobrescrita ? 'concluido' : score.status,
  preliminar: score.preliminar,
  versao_pesos_id: score.versao_pesos_id,
  versao_thresholds_id: score.versao_thresholds_id,
  detalhes_calculo: detalhesAnterior
} }];

